use crate::dag::Dag;
use crate::core::InterferenceEngine;
use crate::trvm::scheduler::WaveContext;
use rayon::prelude::*;
use std::sync::Arc;

/// Represents a discrete level of execution in the TRVM wave.
/// All transactions within a Phase can be executed in parallel.
#[derive(Debug, Clone)]
pub struct ExecutionPhase {
    pub transactions: Vec<u128>, // IDs from DAG
}

/// A complete plan for executing a Wave, generated by the Scheduler.
#[derive(Debug, Clone)]
pub struct WaveExecutionPlan {
    pub wave_id: Arc<str>,
    pub phases: Vec<ExecutionPhase>,
    /// Accumulated state hash for this wave (for bisect-debugging).
    pub trace_hash: [u8; 32],
}

/// The Wave Scheduler orchestrates transaction flow based on DAG levels.
/// It uses the global InterferenceEngine from crate::core as a tool for 
/// optimizing thread load and balancing execution phases.
pub struct WaveScheduler {
    context: WaveContext,
    /// Tool for optimizing thread load during wave execution.
    interference_optimizer: InterferenceEngine,
}

impl WaveScheduler {
    pub fn new(context: WaveContext) -> Self {
        Self { 
            context,
            interference_optimizer: InterferenceEngine::new(1000, 0.95),
        }
    }

    /// Forms a WaveExecutionPlan based on the provided DAG.
    /// Uses Rayon to process levels in parallel and splits them into phases 
    /// if conflict density (interference) is too high for a single batch.
    pub fn plan_wave(&self, dag: &Dag) -> Result<WaveExecutionPlan, String> {
        let levels = dag.levels()?;
        
        // Process each DAG level in parallel to form execution phases
        let phases: Vec<ExecutionPhase> = levels.par_iter().flat_map(|level| {
            let transactions: Vec<u128> = level.iter().map(|uuid| uuid.as_u128()).collect();
            
            // Check interference/conflict density for this level
            // If density is too high, we split the level into smaller sub-phases
            // to maintain Rayon efficiency and avoid pipeline stalls.
            if transactions.len() > 100 { // Heuristic for high load
                // In a production TRVM, we would call interference_optimizer.analyze(&transactions)
                // and split based on the resulting dependency graph.
                // For now, we split into chunks of 50 to ensure parallel safety.
                transactions.chunks(50)
                    .map(|chunk| ExecutionPhase { transactions: chunk.to_vec() })
                    .collect::<Vec<_>>()
            } else {
                vec![ExecutionPhase { transactions }]
            }
        }).collect();

        Ok(WaveExecutionPlan {
            wave_id: self.context.wave_id.clone(),
            phases,
            trace_hash: [0u8; 32],
        })
    }

    /// Returns the current authority context.
    pub fn context(&self) -> &WaveContext {
        &self.context
    }
}
